// app/services/csv-worker.js
self.onmessage = function(e) {
  const { headers, data } = e.data;

  if (!headers || !data) {
    self.postMessage({ status: 'error', error: 'Missing data or headers' });
    return;
  }

  try {
    // 1. Create CSV Header
    const csvRows = [headers.join(',')];

    // 2. Iterate through data and create rows
    for (const row of data) {
      // Escape quotes and commas for robust CSV generation
      const values = headers.map((header) => {
        const val = row[header];
        // Handle nulls/undefined
        const stringVal = val === null || val === undefined ? '' : String(val);

        // Escape double quotes for CSV compliance
        const escapedVal = stringVal.replace(/"/g, '""');

        // Wrap in quotes if it contains commas or quotes (basic protection)
        return `"${escapedVal}"`;
      });

      csvRows.push(values.join(','));
    }

    const csvString = csvRows.join('\n');

    // Send result back to main thread
    self.postMessage({
      status: 'success',
      csv: csvString
    });
  } catch (err) {
    self.postMessage({ status: 'error', error: err.message });
  }
};
